public class IsEnabledExample {
    public static void main(String[] args) {
        WebDriver driver = new ChromeDriver();
        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));

        driver.get("https://example.com/form");

        // Check if button is enabled
        WebElement submitButton = driver.findElement(By.id("submitBtn"));

        if (submitButton.isEnabled()) {
            System.out.println("Button is enabled, clicking...");
            submitButton.click();
        } else {
            System.out.println("Button is disabled, cannot click");
        }

        // Check input field
        WebElement usernameField = driver.findElement(By.id("username"));

        if (usernameField.isEnabled()) {
            usernameField.sendKeys("testuser");
            System.out.println("Username entered");
        } else {
            System.out.println("Username field is disabled");
        }

        // Wait for element to become enabled
        WebElement passwordField = driver.findElement(By.id("password"));

        // Initially disabled, wait for it to be enabled
        wait.until(driver -> passwordField.isEnabled());
        passwordField.sendKeys("password123");
        System.out.println("Password field became enabled and filled");

        // Check multiple fields
        WebElement[] fields = {
            driver.findElement(By.id("firstName")),
            driver.findElement(By.id("lastName")),
            driver.findElement(By.id("email"))
        };

        System.out.println("\nChecking all fields:");
        for (int i = 0; i < fields.length; i++) {
            String fieldName = fields[i].getAttribute("name");
            boolean enabled = fields[i].isEnabled();
            System.out.println(fieldName + " is " + (enabled ? "enabled" : "disabled"));

            if (enabled) {
                fields[i].sendKeys("test data");
            }
        }

        // Verify element state before critical action
        WebElement deleteButton = driver.findElement(By.id("deleteBtn"));

        if (deleteButton.isDisplayed() && deleteButton.isEnabled()) {
            System.out.println("Delete button is ready for interaction");
            deleteButton.click();
        } else {
            System.out.println("Cannot interact with delete button");
        }

        // Check dropdown
        WebElement dropdown = driver.findElement(By.id("country"));
        if (dropdown.isEnabled()) {
            dropdown.click();
            driver.findElement(By.xpath("//option[@value='US']")).click();
        }

        driver.quit();
    }
}
