        System.out.println("Terms checkbox selected: " + termsCheckbox.isSelected());

        // Click to select
        termsCheckbox.click();

        System.out.println("After clicking:");
        System.out.println("Terms checkbox selected: " + termsCheckbox.isSelected());

        // Select checkbox only if not already selected
        WebElement newsletterCheckbox = driver.findElement(By.id("newsletter"));

        if (!newsletterCheckbox.isSelected()) {
            newsletterCheckbox.click();
            System.out.println("Newsletter checkbox selected");
        }

        // Unselect checkbox if selected
        if (newsletterCheckbox.isSelected()) {
            newsletterCheckbox.click();
            System.out.println("Newsletter checkbox unselected");
        }

        // Select multiple checkboxes
        List<WebElement> interestCheckboxes = driver.findElements(By.name("interests"));

        for (WebElement checkbox : interestCheckboxes) {
            if (!checkbox.isSelected()) {
                String value = checkbox.getAttribute("value");
                checkbox.click();
                System.out.println("Selected interest: " + value);
            }
        }

        // Verify specific checkboxes are selected
        WebElement[] requiredCheckboxes = {
            driver.findElement(By.id("consent")),
            driver.findElement(By.id("privacy")),
            driver.findElement(By.id("terms"))
        };

        boolean allSelected = true;
        for (WebElement cb : requiredCheckboxes) {
            if (!cb.isSelected()) {
                allSelected = false;
                System.out.println("Missing required checkbox: " + cb.getAttribute("id"));
            }
        }

        if (allSelected) {
            System.out.println("All required checkboxes are selected!");
        }

        // ===== RADIO BUTTON EXAMPLES =====

        // Select specific radio button
        WebElement maleRadio = driver.findElement(By.id("male"));
        WebElement femaleRadio = driver.findElement(By.id("female"));

        System.out.println("\nRadio button states before selection:");
        System.out.println("Male selected: " + maleRadio.isSelected());
        System.out.println("Female selected: " + femaleRadio.isSelected());

        // Click male radio
        maleRadio.click();

        System.out.println("\nAfter selecting male:");
        System.out.println("Male selected: " + maleRadio.isSelected());
        System.out.println("Female selected: " + femaleRadio.isSelected());

        // Get all radio buttons in a group
