            if (radio.isSelected()) {
                String value = radio.getAttribute("value");
                System.out.println("Selected gender: " + value);
                break;
            }
        }

        // Select radio by value
        String desiredValue = "female";
        for (WebElement radio : genderRadios) {
            if (radio.getAttribute("value").equals(desiredValue)) {
