public class GetCssValueExample {
    public static void main(String[] args) {
        WebDriver driver = new ChromeDriver();
        driver.get("https://example.com");

        WebElement heading = driver.findElement(By.tagName("h1"));

        // Get various CSS properties
        String color = heading.getCssValue("color");
        String fontSize = heading.getCssValue("font-size");
        String fontWeight = heading.getCssValue("font-weight");
        String textAlign = heading.getCssValue("text-align");

        System.out.println("Color: " + color);
        System.out.println("Font Size: " + fontSize);
        System.out.println("Font Weight: " + fontWeight);
        System.out.println("Text Align: " + textAlign);

        // Verify error message is displayed in red
        WebElement error = driver.findElement(By.className("error"));
        String errorColor = error.getCssValue("color");

        if (errorColor.contains("255, 0, 0")) { // RGB for red
            System.out.println("Error message is red - correct!");
        }

        // Check if element is hidden via CSS
        String display = element.getCssValue("display");
        if (display.equals("none")) {
            System.out.println("Element is hidden with display:none");
        }

        driver.quit();
    }
}
