import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.support.ui.Select;
import java.util.List;

public class DropdownExample {
    public static void main(String[] args) {
        WebDriver driver = new ChromeDriver();
        driver.get("https://example.com/form");

        // ===== BASIC DROPDOWN SELECTION =====

        // 1. Find the <select> element
        WebElement countryDropdown = driver.findElement(By.id("country"));

        // 2. Create Select object
        Select selectCountry = new Select(countryDropdown);

        // 3. Select by visible text
        selectCountry.selectByVisibleText("United States");
        System.out.println("Selected by visible text: United States");

        // 4. Select by value attribute
        selectCountry.selectByValue("US");
        System.out.println("Selected by value: US");

        // 5. Select by index (0-based)
        selectCountry.selectByIndex(2); // Selects 3rd option
        System.out.println("Selected by index: 2");

        // ===== GET SELECTED OPTION =====

        WebElement selectedOption = selectCountry.getFirstSelectedOption();
        String selectedText = selectedOption.getText();
        String selectedValue = selectedOption.getAttribute("value");

        System.out.println("Currently selected text: " + selectedText);
        System.out.println("Currently selected value: " + selectedValue);

        // ===== GET ALL OPTIONS =====

        List<WebElement> allOptions = selectCountry.getOptions();
        System.out.println("\nAll dropdown options:");

        for (int i = 0; i < allOptions.size(); i++) {
            WebElement option = allOptions.get(i);
            System.out.println(i + ". " + option.getText() + " (value=" + option.getAttribute("value") + ")");
        }

        // ===== VERIFY DROPDOWN CONTAINS OPTION =====

        boolean hasCanada = false;
        for (WebElement option : allOptions) {
            if (option.getText().equals("Canada")) {
                hasCanada = true;
                break;
            }
        }

        if (hasCanada) {
            selectCountry.selectByVisibleText("Canada");
            System.out.println("\nCanada found and selected");
        }

        // ===== MULTI-SELECT DROPDOWN =====

        WebElement skillsDropdown = driver.findElement(By.id("skills"));
        Select selectSkills = new Select(skillsDropdown);

        // Check if multi-select
        if (selectSkills.isMultiple()) {
            System.out.println("\nThis is a multi-select dropdown");

            // Select multiple options
            selectSkills.selectByVisibleText("Java");
            selectSkills.selectByVisibleText("Python");
            selectSkills.selectByValue("javascript");

            // Get all selected options
            List<WebElement> selectedOptions = selectSkills.getAllSelectedOptions();
            System.out.println("Selected skills:");
            for (WebElement option : selectedOptions) {
                System.out.println("- " + option.getText());
            }

            // Deselect specific option
            selectSkills.deselectByVisibleText("Python");
            System.out.println("Deselected Python");

            // Deselect all
            selectSkills.deselectAll();
            System.out.println("Deselected all options");
        }

        // ===== SELECT BY PARTIAL TEXT MATCH =====

        WebElement stateDropdown = driver.findElement(By.id("state"));
        Select selectState = new Select(stateDropdown);

        String partialText = "New York";
        for (WebElement option : selectState.getOptions()) {
            if (option.getText().contains(partialText)) {
                option.click();
                System.out.println("\nSelected state containing: " + partialText);
                break;
            }
        }

        // ===== DROPDOWN VALIDATION =====

        WebElement monthDropdown = driver.findElement(By.id("month"));
        Select selectMonth = new Select(monthDropdown);

        // Verify dropdown has expected number of options
        int optionCount = selectMonth.getOptions().size();
        if (optionCount == 12) {
            System.out.println("\nMonth dropdown has correct 12 options");
        }

        // Verify first option is placeholder
        WebElement firstOption = selectMonth.getOptions().get(0);
        if (firstOption.getText().equals("Select Month")) {
            System.out.println("Placeholder text is correct");
        }

        // Select option and verify
        selectMonth.selectByVisibleText("January");
        String selected = selectMonth.getFirstSelectedOption().getText();
        if (selected.equals("January")) {
            System.out.println("January successfully selected");
        }

        // ===== DYNAMIC DROPDOWN (Wait for options to load) =====

        WebElement cityDropdown = driver.findElement(By.id("city"));
        Select selectCity = new Select(cityDropdown);

        // Wait for options to populate (AJAX dropdown)
        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));
        wait.until(driver -> selectCity.getOptions().size() > 1);

        System.out.println("\nCity options loaded: " + selectCity.getOptions().size());
        selectCity.selectByIndex(1);

        driver.quit();
    }
}
