public class CompleteFormAutomation {
    public static void main(String[] args) {
        WebDriver driver = new ChromeDriver();
        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));

        try {
            // Navigate to form page
            driver.get("https://example.com/registration-form");
            driver.manage().window().maximize();
            System.out.println("✓ Navigated to registration form");

            // ===== 1. FILL TEXT INPUT FIELDS =====

            // First Name
            WebElement firstName = wait.until(
                ExpectedConditions.visibilityOfElementLocated(By.id("firstName"))
            );
            firstName.clear();
            firstName.sendKeys("John");
            System.out.println("✓ Entered first name");

            // Last Name
            WebElement lastName = driver.findElement(By.id("lastName"));
            lastName.clear();
            lastName.sendKeys("Doe");
            System.out.println("✓ Entered last name");

            // Email
