            email.clear();
            email.sendKeys("john.doe@example.com");
            System.out.println("✓ Entered email");

            // Password
            WebElement password = driver.findElement(By.id("password"));
            password.clear();
            password.sendKeys("SecurePass123!");
            System.out.println("✓ Entered password");

            // Confirm Password
            WebElement confirmPassword = driver.findElement(By.id("confirmPassword"));
            confirmPassword.clear();
            confirmPassword.sendKeys("SecurePass123!");
            System.out.println("✓ Entered confirm password");

            // Phone Number
            WebElement phone = driver.findElement(By.id("phone"));
            phone.clear();
            phone.sendKeys("555-123-4567");
            System.out.println("✓ Entered phone number");

            // Address (Textarea)
            WebElement address = driver.findElement(By.id("address"));
            address.clear();
            address.sendKeys("123 Main Street\nApt 4B\nNew York, NY 10001");
            System.out.println("✓ Entered address");

            // ===== 2. SELECT DROPDOWN OPTIONS =====

            // Country Dropdown
            WebElement countryDropdown = driver.findElement(By.id("country"));
            Select selectCountry = new Select(countryDropdown);
            selectCountry.selectByVisibleText("United States");
            System.out.println("✓ Selected country: United States");

            // State Dropdown (may load after country selection)
            Thread.sleep(1000); // Wait for state dropdown to populate
            WebElement stateDropdown = driver.findElement(By.id("state"));
            Select selectState = new Select(stateDropdown);
            selectState.selectByValue("NY");
            System.out.println("✓ Selected state: NY");

            // Occupation Dropdown
            WebElement occupationDropdown = driver.findElement(By.id("occupation"));
            Select selectOccupation = new Select(occupationDropdown);
            selectOccupation.selectByIndex(2); // Select 3rd option
            System.out.println("✓ Selected occupation");

            // ===== 3. SELECT RADIO BUTTONS =====

            // Gender Radio Buttons
            List<WebElement> genderRadios = driver.findElements(By.name("gender"));
            for (WebElement radio : genderRadios) {
                if (radio.getAttribute("value").equals("male")) {
                    radio.click();
                    System.out.println("✓ Selected gender: Male");
                    break;
                }
            }

            // Age Group Radio
            WebElement ageRadio = driver.findElement(By.id("age25-34"));
            ageRadio.click();
            System.out.println("✓ Selected age group: 25-34");

            // ===== 4. SELECT CHECKBOXES =====

            // Terms and Conditions (Required)
            WebElement termsCheckbox = driver.findElement(By.id("terms"));
            if (!termsCheckbox.isSelected()) {
                termsCheckbox.click();
                System.out.println("✓ Accepted terms and conditions");
            }

            // Newsletter Subscription (Optional)
            WebElement newsletterCheckbox = driver.findElement(By.id("newsletter"));
            if (!newsletterCheckbox.isSelected()) {
                newsletterCheckbox.click();
                System.out.println("✓ Subscribed to newsletter");
            }

            // Interests (Multiple checkboxes)
            String[] interests = {"technology", "sports", "music"};
            for (String interest : interests) {
                WebElement interestCheckbox = driver.findElement(By.id(interest));
                if (!interestCheckbox.isSelected()) {
                    interestCheckbox.click();
                    System.out.println("✓ Selected interest: " + interest);
                }
            }

            // ===== 5. VERIFY ALL FIELD VALUES =====

            System.out.println("\n=== Verifying Form Data ===");

            // Verify text inputs
            String firstNameValue = firstName.getAttribute("value");
            String lastNameValue = lastName.getAttribute("value");
            String emailValue = email.getAttribute("value");

