                throw new RuntimeException("First name verification failed!");
            }

            // Verify dropdown selections
            String selectedCountry = selectCountry.getFirstSelectedOption().getText();
            String selectedState = selectState.getFirstSelectedOption().getText();

            System.out.println("Country: " + selectedCountry);
