            WebElement submitButton = driver.findElement(By.id("submitBtn"));

            // Verify button is enabled
            if (!submitButton.isEnabled()) {
                throw new RuntimeException("Submit button is disabled!");
            }

            // Scroll to submit button
            ((JavascriptExecutor) driver).executeScript(
                "arguments[0].scrollIntoView(true);", submitButton
            );

            // Click submit
            submitButton.click();
            System.out.println("\n✓ Form submitted");

            // ===== 7. VALIDATE SUCCESS MESSAGE =====

            // Wait for success message to appear
            WebElement successMessage = wait.until(
                ExpectedConditions.visibilityOfElementLocated(By.className("success-message"))
            );

            String messageText = successMessage.getText();
            System.out.println("\nSuccess Message: " + messageText);

            // Verify message contains expected text
            if (messageText.contains("Registration Successful") || 
                messageText.contains("Thank you")) {
                System.out.println("✓ Success message validated");
            } else {
                throw new RuntimeException("Unexpected success message: " + messageText);
            }

            // Verify URL changed to confirmation page
            String currentUrl = driver.getCurrentUrl();
            if (currentUrl.contains("confirmation") || currentUrl.contains("success")) {
                System.out.println("✓ Redirected to confirmation page");
            }

            // Wait to see result
            Thread.sleep(2000);

            System.out.println("\n=== Form Automation Completed Successfully ===");

        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
            e.printStackTrace();
        } finally {
            driver.quit();
            System.out.println("✓ Browser closed");
        }
    }
}
